ign-self: stretch;\n          text-align: center;\n          color: #1a202e;\n          font-size: 20px;\n          font-family: HarmonyOS Sans SC;\n          font-weight: 700;\n          line-height: 30px;\n          word-wrap: break-word;\n        \">\n                Inventory Alert\n            </div>\n        </div>\n        <div style=\"\n        align-self: stretch;\n        padding-left: 48px;\n        padding-right: 48px;\n        flex-direction: column;\n        justify-content: flex-start;\n        align-items: flex-start;\n        gap: 24px;\n        display: flex;\n      \">\n            <div style=\"\n          align-self: stretch;\n          flex-direction: column;\n          justify-content: flex-start;\n          align-items: flex-start;\n          gap: 8px;\n          display: flex;\n        \">\n                <div style=\"\n            align-self: stretch;\n            color: #767676;\n            font-size: 16px;\n            font-family: HarmonyOS Sans SC;\n            font-weight: 400;\n            line-height: 24px;\n            word-wrap: break-word;\n          \">\n                    Dear Management Team of {{company}},\n                </div>\n                <div style=\"align-self: stretch\">\n                    <span style=\"\n              color: #767676;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 400;\n              line-height: 24px;\n              word-wrap: break-word;\n            \">The system has detected that the inventory of your store\'s </span><span style=\"\n              color: #333333;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 700;\n              line-height: 24px;\n              word-wrap: break-word;\n            \">{{material}}</span><span style=\"\n              color: #767676;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 400;\n              line-height: 24px;\n              word-wrap: break-word;\n            \"> has fallen below the preset safety stock level. Please arrange for timely replenishment to avoid any\n                        impact on normal sales operations.</span>\n                </div>\n            </div>\n            <div style=\"\n          align-self: stretch;\n          height: 0px;\n          opacity: 0.5;\n          outline: 1px #ebebeb solid;\n          outline-offset: -0.5px;\n        \"></div>\n            <div style=\"\n          align-self: stretch;\n          flex-direction: column;\n          justify-content: flex-start;\n          align-items: flex-start;\n          gap: 8px;\n          display: flex;\n        \">\n                <div style=\"\n            align-self: stretch;\n            color: #1a202e;\n            font-size: 16px;\n            font-family: HarmonyOS Sans SC;\n            font-weight: 400;\n            line-height: 24px;\n            word-wrap: break-word;\n          \">\n                    Alert Details are as follows:​\n                </div>\n                <div style=\"\n            align-self: stretch;\n            justify-content: flex-start;\n            align-items: flex-start;\n            gap: 64px;\n            display: inline-flex;\n          \">\n                    <div style=\"\n              color: #333333;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 400;\n              line-height: 24px;\n              word-wrap: break-word;\n            \">\n                        Material Name:\n                    </div>\n                    <div style=\"\n              color: #1a202e;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 500;\n              line-height: 24px;\n              word-wrap: break-word;\n            \">\n                        {{material}}​\n                    </div>\n                </div>\n                <div style=\"\n            align-self: stretch;\n            justify-content: flex-start;\n            align-items: flex-start;\n            gap: 64px;\n            display: inline-flex;\n          \">\n                    <div style=\"\n              color: #333333;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 400;\n              line-height: 24px;\n              word-wrap: break-word;\n            \">\n                        Current Store Inventory:\n                    </div>\n                    <div style=\"\n              color: #1a202e;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 500;\n              line-height: 24px;\n              word-wrap: break-word;\n            \">\n                        {{current_stock}}\n                    </div>\n                </div>\n                <div style=\"\n            align-self: stretch;\n            justify-content: flex-start;\n            align-items: flex-start;\n            gap: 64px;\n            display: inline-flex;\n          \">\n                    <div style=\"\n              color: #333333;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 400;\n              line-height: 24px;\n              word-wrap: break-word;\n            \">\n                        Preset Safety Stock:\n                    </div>\n                    <div style=\"\n              color: #1a202e;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 500;\n              line-height: 24px;\n              word-wrap: break-word;\n            \">\n                        {{safety_stock}}\n                    </div>\n                </div>\n                <div style=\"\n            align-self: stretch;\n            justify-content: flex-start;\n            align-items: flex-start;\n            gap: 64px;\n            display: inline-flex;\n          \">\n                    <div style=\"\n              color: #333333;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 400;\n              line-height: 24px;\n              word-wrap: break-word;\n            \">\n                        Alert Trigger Time:\n                    </div>\n                    <div style=\"\n              color: #1a202e;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 500;\n              line-height: 24px;\n              word-wrap: break-word;\n            \">\n                        {{time}}\n                    </div>\n                </div>\n            </div>\n            <div style=\"\n          align-self: stretch;\n          height: 0px;\n          opacity: 0.5;\n          outline: 1px #ebebeb solid;\n          outline-offset: -0.5px;\n        \"></div>\n            <div style=\"\n          align-self: stretch;\n          flex-direction: column;\n          justify-content: flex-start;\n          align-items: flex-start;\n          gap: 4px;\n          display: flex;\n        \">\n                <div style=\"\n            align-self: stretch;\n            color: #767676;\n            font-size: 16px;\n            font-family: HarmonyOS Sans SC;\n            font-weight: 400;\n            line-height: 24px;\n            word-wrap: break-word;\n          \">\n                    Please instruct the relevant responsible colleagues to verify the inventory immediately and initiate\n                    a\n                    purchase order. If a purchase order has already been submitted, this email may be ignored.​\n                </div>\n                <div style=\"\n            align-self: stretch;\n            color: #767676;\n            font-size: 16px;\n            font-family: HarmonyOS Sans SC;\n            font-weight: 400;\n            line-height: 24px;\n            word-wrap: break-word;\n          \">\n                    Thank you for your prompt attention and handling. Best regards!\n                </div>\n            </div>\n            <div style=\"\n          align-self: stretch;\n          flex-direction: column;\n          justify-content: flex-start;\n          align-items: flex-end;\n          gap: 4px;\n          display: flex;\n        \">\n                <div style=\"\n            align-self: stretch;\n            color: #767676;\n            font-size: 16px;\n            font-family: HarmonyOS Sans SC;\n            font-weight: 400;\n            line-height: 24px;\n            word-wrap: break-word;\n          \">\n                    TTPOS\n                </div>\n                <div style=\"\n            align-self: stretch;\n            color: #767676;\n            font-size: 16px;\n            font-family: HarmonyOS Sans SC;\n            font-weight: 400;\n            line-height: 24px;\n            word-wrap: break-word;\n          \">\n                    {{date}}\n                </div>\n            </div>\n        </div>\n    </div>\n</div>', '{\"date\": \"发送日期\", \"time\": \"发送时间\", \"company\": \"公司名称\", \"material\": \"物品名称\", \"safety_stock\": \"安全库存\", \"current_stock\": \"当前库存\"}', 1, '门店物品库存不足模板', unix_timestamp(), unix_timestamp(), 0);
INSERT INTO `message`.`message_template` (`uuid`, `template_name`, `template_type`, `template_subject`, `template_content`, `template_args`, `status`, `remark`, `created_at`, `updated_at`, `deleted_at`) VALUES ('tpl_warehouse_safety_stock_alert', '仓库物品库存不足', 'email', '[Alert] {{company}} - {{warehouse}} - Insufficient Safety Stock of {{material}}!', '<style>\n    /* Mobile-first overrides for inline fixed sizes */\n    html,\n    body {\n        margin: 0;\n        padding: 0;\n    }\n\n    #email-root {\n        width: 100% !important;\n        max-width: 1440px;\n        margin: 0 auto;\n        padding-left: 16px !important;\n        padding-right: 16px !important;\n        box-sizing: border-box;\n    }\n\n    #email-card {\n        width: 100% !important;\n        max-width: 800px;\n        box-sizing: border-box;\n    }\n\n    /* Make inline-flex rows wrap on small screens and reduce gaps */\n    @media (max-width: 600px) {\n        [style*=\"display: inline-flex\"] {\n            flex-wrap: wrap !important;\n            gap: 12px !important;\n        }\n\n        [style*=\"gap: 64px\"] {\n            gap: 12px !important;\n        }\n\n        [style*=\"padding-left: 48px\"] {\n            padding-left: 16px !important;\n        }\n\n        [style*=\"padding-right: 48px\"] {\n            padding-right: 16px !important;\n        }\n\n        [style*=\"font-size: 20px\"] {\n            font-size: 18px !important;\n            line-height: 26px !important;\n        }\n\n        [style*=\"font-size: 16px\"] {\n            font-size: 14px !important;\n            line-height: 22px !important;\n        }\n\n\n    }\n\n    /* Tablet */\n    @media (min-width: 600px) and (max-width: 1023px) {\n        #email-root {\n            padding-left: 24px !important;\n            padding-right: 24px !important;\n        }\n    }\n\n    /* Desktop keeps original generous paddings */\n    @media (min-width: 1024px) {\n        #email-root {\n            padding-left: 381px !important;\n            padding-right: 381px !important;\n        }\n    }\n</style>\n<div id=\"email-root\" style=\"\n    width: 1440px;\n    padding-left: 381px;\n    padding-right: 381px;\n    padding-top: 64px;\n    padding-bottom: 64px;\n    background: #f9f4f0;\n    flex-direction: column;\n    justify-content: center;\n    align-items: center;\n    gap: 24px;\n    display: inline-flex;\n  \">\n    <div style=\"\n      width: 560px;\n      padding-left: 48px;\n      padding-right: 48px;\n      flex-direction: row;\n      justify-content: center;\n      align-items: center;\n      gap: 10px;\n      display: flex;\n    \">\n        <div style=\"width: 161.4px; height: 28px; position: relative\">\n            <div data-svg-wrapper style=\"left: 0px; top: 0px; position: absolute\">\n                <svg width=\"44\" height=\"28\" viewBox=\"0 0 44 28\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n                    <path\n                        d=\"M43.9292 0V8.60021H43.8978V20.4468L28.8968 20.4625V27.9552L19.7047 28V12.9833H34.8268V8.64505L0 8.6159V0.0291456L43.9292 0Z\"\n                        fill=\"#FF6C1F\" />\n                </svg>\n            </div>\n            <div data-svg-wrapper style=\"left: 1.76px; top: 13.15px; position: absolute\">\n                <svg width=\"13\" height=\"15\" viewBox=\"0 0 13 15\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n                    <path d=\"M12.7299 0H0V14.8419H12.7299V0Z\" fill=\"#FF6C1F\" />\n                </svg>\n            </div>\n            <div data-svg-wrapper style=\"left: 142.78px; top: 2px; position: absolute\">\n                <svg width=\"19\" height=\"24\" viewBox=\"0 0 19 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n                    <path\n                        d=\"M0 15.8438L4.5 15.4062C4.77083 16.9167 5.31771 18.026 6.14063 18.7344C6.97396 19.4427 8.09375 19.7969 9.5 19.7969C10.9896 19.7969 12.1094 19.4844 12.8594 18.8594C13.6198 18.224 14 17.4844 14 16.6406C