  align-self: stretch;\n          text-align: center;\n          color: #1a202e;\n          font-size: 20px;\n          font-family: HarmonyOS Sans SC;\n          font-weight: 700;\n          line-height: 30px;\n          word-wrap: break-word;\n        \">\n                Inventory Alert\n            </div>\n        </div>\n        <div style=\"\n        align-self: stretch;\n        padding-left: 48px;\n        padding-right: 48px;\n        flex-direction: column;\n        justify-content: flex-start;\n        align-items: flex-start;\n        gap: 24px;\n        display: flex;\n      \">\n            <div style=\"\n          align-self: stretch;\n          flex-direction: column;\n          justify-content: flex-start;\n          align-items: flex-start;\n          gap: 8px;\n          display: flex;\n        \">\n                <div style=\"\n            align-self: stretch;\n            color: #767676;\n            font-size: 16px;\n            font-family: HarmonyOS Sans SC;\n            font-weight: 400;\n            line-height: 24px;\n            word-wrap: break-word;\n          \">\n                    Dear Management Team of {{company}},\n                </div>\n                <div style=\"align-self: stretch\">\n                    <span style=\"\n              color: #767676;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 400;\n              line-height: 24px;\n              word-wrap: break-word;\n            \">The system has detected that the inventory of </span><span style=\"\n              color: #333333;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 700;\n              line-height: 24px;\n              word-wrap: break-word;\n            \">{{material}}</span><span style=\"\n              color: #767676;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 400;\n              line-height: 24px;\n              word-wrap: break-word;\n            \"> in the </span>\n                    <span style=\"\n              color: #333333;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 700;\n              line-height: 24px;\n              word-wrap: break-word;\n            \">{{warehouse}}</span><span style=\"\n              color: #767676;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 400;\n              line-height: 24px;\n              word-wrap: break-word;\n            \"> of your store has fallen below the preset safety stock level. Please replenish it in a timely manner to\n                        avoid affecting normal sales.</span>\n                </div>\n            </div>\n            <div style=\"\n          align-self: stretch;\n          height: 0px;\n          opacity: 0.5;\n          outline: 1px #ebebeb solid;\n          outline-offset: -0.5px;\n        \"></div>\n            <div style=\"\n          align-self: stretch;\n          flex-direction: column;\n          justify-content: flex-start;\n          align-items: flex-start;\n          gap: 8px;\n          display: flex;\n        \">\n                <div style=\"\n            align-self: stretch;\n            color: #1a202e;\n            font-size: 16px;\n            font-family: HarmonyOS Sans SC;\n            font-weight: 400;\n            line-height: 24px;\n            word-wrap: break-word;\n          \">\n                    Alert Details are as follows:​\n                </div>\n                <div style=\"\n            align-self: stretch;\n            justify-content: flex-start;\n            align-items: flex-start;\n            gap: 64px;\n            display: inline-flex;\n          \">\n                    <div style=\"\n              color: #333333;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 400;\n              line-height: 24px;\n              word-wrap: break-word;\n            \">\n                        Material Name:\n                    </div>\n                    <div style=\"\n              color: #1a202e;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 500;\n              line-height: 24px;\n              word-wrap: break-word;\n            \">\n                        {{material}}​\n                    </div>\n                </div>\n                <div style=\"\n            align-self: stretch;\n            justify-content: flex-start;\n            align-items: flex-start;\n            gap: 64px;\n            display: inline-flex;\n          \">\n                    <div style=\"\n              color: #333333;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 400;\n              line-height: 24px;\n              word-wrap: break-word;\n            \">\n                        Warehouse Inventory:\n                    </div>\n                    <div style=\"\n              color: #1a202e;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 500;\n              line-height: 24px;\n              word-wrap: break-word;\n            \">\n                        {{current_stock}}\n                    </div>\n                </div>\n                <div style=\"\n            align-self: stretch;\n            justify-content: flex-start;\n            align-items: flex-start;\n            gap: 64px;\n            display: inline-flex;\n          \">\n                    <div style=\"\n              color: #333333;\n              font-size: 16px;\n              font-family: HarmonyOS Sans SC;\n              font-weight: 400;\n              line-height: 24px;\n              word-wrap: break-word;\n            \">\n                        Preset Safety Stock:\n     